
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_edf1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_edf1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.428886966670527e+00, -4.343750503456526e+00, -4.224558583180261e+00, -4.059672913652401e+00, -3.835483987792806e+00, -3.538187556672057e+00, -3.157979380759464e+00, -2.696761213042927e+00, -2.178669245910379e+00, -1.651637371690653e+00, -1.132119537439189e+00, -7.532282234827274e-01, -6.517178232012786e-01, -5.357908824724367e-01, -3.881417166587453e-01, -2.542172728246468e-01, -1.784557828633409e-01, -1.492404397314931e-01, -1.117425032186536e-01, -8.075958835225917e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


